1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface QuoteItem {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: QuoteItem[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: {
26	    cause: string;
27	    damages: Damage[];
28	  };
29	}
30	
31	export type Step = QuoteStep | ClaimStep;
32	
33	export interface Scenario {
34	  customer: Customer;
35	  steps: Step[];
36	}
37	
38	export interface QuoteResult {
39	  premium: number;
40	}
41	
42	export interface ClaimResult {
43	  payout: number;
44	  remainingCap: number;
45	}
46	
47	export type StepResult = QuoteResult | ClaimResult;
48	
49	export interface ScenarioOutput {
50	  results: StepResult[];
51	}
52	
53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_RATE = 0.1;
55	const CURSE_SURCHARGE_RATE = 0.5;
56	const HIGH_ENCHANTMENT_THRESHOLD = 5;
57	const ENCHANTMENT_SURCHARGE_RATE = 0.3;
58	const LOYALTY_MIN_YEARS = 2;
59	const LOYALTY_DISCOUNT_RATE = 0.2;
60	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
61	
62	const BASE_PREMIUMS: Record<string, number> = {
63	  sword: 100,
64	  amulet: 60,
65	  staff: 80,
66	  potion: 40,
67	  rune: 25,
68	  moonstone: 25,
69	};
70	
71	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
72	const COMPONENT_BLOCK_SIZE = 3;
73	const COMPONENT_BLOCK_PREMIUM = 60;
74	
75	const roundUpInMHPCOsFavor = Math.ceil;
76	const roundDownInMHPCOsFavor = Math.floor;
77	
78	const basePremiumFor = (type: string, count: number): number => {
79	  const unitPremium = BASE_PREMIUMS[type];
80	  if (unitPremium === undefined) {
81	    throw new Error(`unknown item type: "${type}"`);
82	  }
83	  const isComponentBlock =
84	    COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
85	  return isComponentBlock ? COMPONENT_BLOCK_PREMIUM : count * unitPremium;
86	};
87	
88	const countBy = <T>(
89	  items: T[],
90	  typeOf: (item: T) => string,
91	): Map<string, number> => {
92	  const countsByType = new Map<string, number>();
93	  for (const item of items) {
94	    const type = typeOf(item);
95	    countsByType.set(type, (countsByType.get(type) ?? 0) + 1);
96	  }
97	  return countsByType;
98	};
99	
100	const countItemsByType = (items: QuoteItem[]): Map<string, number> =>
101	  countBy(items, (item) => item.type);
102	
103	const isCursed = (item: QuoteItem): boolean => item.cursed === true;
104	
105	const isHighlyEnchanted = (item: QuoteItem): boolean =>
106	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
107	
108	const perItemSurcharge = (
109	  items: QuoteItem[],
110	  applies: (item: QuoteItem) => boolean,
111	  rate: number,
112	): number =>
113	  items.reduce(
114	    (total, item) =>
115	      total + (applies(item) ? BASE_PREMIUMS[item.type] * rate : 0),
116	    0,
117	  );
118	
119	const quotePremium = (
120	  items: QuoteItem[],
121	  customer: Customer,
122	  isFollowUpContract: boolean,
123	): number => {
124	  const basePremium = [...countItemsByType(items)].reduce(
125	    (total, [type, count]) => total + basePremiumFor(type, count),
126	    0,
127	  );
128	  const curseSurcharge = perItemSurcharge(items, isCursed, CURSE_SURCHARGE_RATE);
129	  const enchantmentSurcharge = perItemSurcharge(
130	    items,
131	    isHighlyEnchanted,
132	    ENCHANTMENT_SURCHARGE_RATE,
133	  );
134	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_RATE;
135	  const loyaltyDiscount =
136	    customer.yearsWithMHPCO >= LOYALTY_MIN_YEARS
137	      ? basePremium * LOYALTY_DISCOUNT_RATE
138	      : 0;
139	  const followUpDiscount = isFollowUpContract
140	    ? basePremium * FOLLOW_UP_DISCOUNT_RATE
141	    : 0;
142	  return roundUpInMHPCOsFavor(
143	    basePremium +
144	      curseSurcharge +
145	      enchantmentSurcharge +
146	      firstInsuranceSurcharge -
147	      loyaltyDiscount -
148	      followUpDiscount +
149	      PROCESSING_FEE,
150	  );
151	};
152	
153	const INSURANCE_VALUES: Record<string, number> = {
154	  sword: 1000,
155	  amulet: 600,
156	  rune: 250,
157	};
158	
159	const DEDUCTIBLE = 100;
160	const PAYOUT_CAP_MULTIPLIER = 2;
161	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
162	const HALF_REIMBURSEMENT_RATE = 0.5;
163	
164	const reimbursementFor = (damage: Damage, policyItems: QuoteItem[]): number => {
165	  const damagedItem = policyItems.find(
166	    (item) => item.type === damage.itemType,
167	  );
168	  const isHalfReimbursed =
169	    (damagedItem?.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
170	  return isHalfReimbursed
171	    ? damage.amount * HALF_REIMBURSEMENT_RATE
172	    : damage.amount;
173	};
174	
175	const assertDamagesWithinInsuredCounts = (
176	  damages: Damage[],
177	  policyItems: QuoteItem[],
178	): void => {
179	  const insuredCounts = countItemsByType(policyItems);
180	  for (const [type, damageCount] of countBy(
181	    damages,
182	    (damage) => damage.itemType,
183	  )) {
184	    const insuredCount = insuredCounts.get(type) ?? 0;
185	    if (damageCount > insuredCount) {
186	      throw new Error(
187	        `claim rejected: ${damageCount} damage entries for "${type}" but only ${insuredCount} insured`,
188	      );
189	    }
190	  }
191	};
192	
193	const assertNoNegativeDamageAmounts = (damages: Damage[]): void => {
194	  for (const damage of damages) {
195	    if (damage.amount < 0) {
196	      throw new Error(`claim rejected: negative damage amount ${damage.amount}`);
197	    }
198	  }
199	};
200	
201	const settleClaim = (
202	  claimStep: ClaimStep,
203	  policyItems: QuoteItem[],
204	  remainingCapBefore: number,
205	): ClaimResult => {
206	  const { damages } = claimStep.incident;
207	  assertNoNegativeDamageAmounts(damages);
208	  assertDamagesWithinInsuredCounts(damages, policyItems);
209	  const uncappedPayout = roundDownInMHPCOsFavor(
210	    damages.reduce(
211	      (total, damage) =>
212	        total + (reimbursementFor(damage, policyItems) - DEDUCTIBLE),
213	      0,
214	    ),
215	  );
216	  const payout = Math.min(uncappedPayout, remainingCapBefore);
217	  return { payout, remainingCap: remainingCapBefore - payout };
218	};
219	
220	const initialPayoutCap = (policyItems: QuoteItem[]): number => {
221	  const insuranceSum = policyItems.reduce(
222	    (sum, item) => sum + INSURANCE_VALUES[item.type],
223	    0,
224	  );
225	  return insuranceSum * PAYOUT_CAP_MULTIPLIER;
226	};
227	
228	export const runScenario = (scenario: Scenario): ScenarioOutput => {
229	  const remainingCapByPolicy = new Map<number, number>();
230	  const results = scenario.steps.map((step, stepIndex): StepResult => {
231	    if (step.op === "claim") {
232	      const policyStep = scenario.steps[step.policy] as QuoteStep;
233	      const remainingCapBefore =
234	        remainingCapByPolicy.get(step.policy) ??
235	        initialPayoutCap(policyStep.items);
236	      const result = settleClaim(step, policyStep.items, remainingCapBefore);
237	      remainingCapByPolicy.set(step.policy, result.remainingCap);
238	      return result;
239	    }
240	    const isFollowUpContract = stepIndex > 0;
241	    return {
242	      premium: quotePremium(step.items, scenario.customer, isFollowUpContract),
243	    };
244	  });
245	  return { results };
246	};
